const input = $input.all();

// get the first incoming item's JSON
const quote = input[0].json.data;

// find the Materials section
const materialsSection = quote.sections.find(
  section => section.name.toLowerCase() === 'materials'
);

if (!materialsSection) {
  throw new Error('Materials section not found in Fergus quote');
}

// Extract each material
const materials = materialsSection.lineItems.map(item => ({
  name: item.itemName,
  quantity: Number(item.itemQuantity),
  unit: item.unitOfMeasureSell,
  estimatedUnitCost: Number(item.itemCost),
  estimatedTotalCost:
    Number(item.itemQuantity) * Number(item.itemCost),
}));

// calculate total estimated material cost
// this assumes that each estimatedTotalCost is number
// else this should return NaN (have to verify later)
const estimatedMaterialCost = materials.reduce(
  (sum, item) => sum + item.estimatedTotalCost,
  0
);

return [{
  json: {
    jobId: quote.jobId,
    jobNo: quote.jobNo,
    quoteId: quote.id,
    quoteTitle: quote.title,
    estimatedMaterialCost,
    materials
  }
}];

const invoice = $('AI Invoice Extractor').first().json;
const fergus = $input.first().json;

const invoiceItemsList = invoice.output.materials.map((item, i) => 
  `${i}: ${item.description} (qty: ${item.qty} ${item.unit}, unit price: $${item.unit_price})`
).join('\n');

const fergusItemsList = fergus.materials.map((item, i) => 
  `${i}: ${item.name} (qty: ${item.quantity} ${item.unit || 'unit'}, est. unit cost: $${item.estimatedUnitCost})`
).join('\n');

return [{
  json: {
    invoice,
    fergus,
    invoice_items_list: invoiceItemsList,
    fergus_items_list: fergusItemsList
  }
}];

const { matches, unmatchedInvoiceItems, unmatchedFergusItems } = $input.first().json.output;

const lowConfidenceMatches = matches.filter(m => m.confidence < 0.75);

return [{
  json: {
    ...$input.first().json.output,
    lowConfidenceMatches,
    needsReview: lowConfidenceMatches.length > 0 
      || unmatchedInvoiceItems.length > 0 
      || unmatchedFergusItems.length > 0
  }
}];

const matchData = $input.first().json; // matches, unmatchedInvoiceItems, etc.
const merged = $('Prepare Comparison Data').first().json; // merged data

const invoiceMaterials = merged.invoice.output.materials;
const fergusMaterials = merged.fergus.materials;

const variances = matchData.matches.map(m => {
  const invItem = invoiceMaterials[m.invoiceItemIndex];
  const fergusItem = fergusMaterials[m.fergusItemIndex];

  const actualTotal = invItem.amount;
  const estimatedTotal = fergusItem.estimatedTotalCost;
  const costVarianceAmount = Math.round((actualTotal - estimatedTotal) * 100) / 100;
  const costVariancePct = estimatedTotal !== 0 
    ? Math.round((costVarianceAmount / estimatedTotal) * 1000) / 10 
    : null;

  const qtyInvoice = invItem.qty;
  const qtyFergus = fergusItem.quantity;
  const qtyVarianceAmount = Math.round((qtyInvoice - qtyFergus) * 100) / 100;
  const qtyVariancePct = qtyFergus !== 0 
    ? Math.round((qtyVarianceAmount / qtyFergus) * 1000) / 10 
    : null;

  // unit price variance in isolation — did the per-unit rate itself change,
  // independent of quantity?
  const unitPriceVarianceAmount = Math.round((invItem.unit_price - fergusItem.estimatedUnitCost) * 100) / 100;
  const unitPriceVariancePct = fergusItem.estimatedUnitCost !== 0
    ? Math.round((unitPriceVarianceAmount / fergusItem.estimatedUnitCost) * 1000) / 10
    : null;

  return {
    invoiceDescription: invItem.description,
    fergusDescription: fergusItem.name,
    matchConfidence: m.confidence,
    qtyInvoice,
    qtyFergus,
    qtyVarianceAmount,
    qtyVariancePct,
    unitPriceInvoice: invItem.unit_price,
    unitPriceFergus: fergusItem.estimatedUnitCost,
    unitPriceVarianceAmount,
    unitPriceVariancePct,
    actualTotal,
    estimatedTotal,
    costVarianceAmount,
    costVariancePct
  };
});

const totalActual = variances.reduce((s, v) => s + v.actualTotal, 0);
const totalEstimated = variances.reduce((s, v) => s + v.estimatedTotal, 0);
const totalCostVariance = Math.round((totalActual - totalEstimated) * 100) / 100;

const totalCostVariancePct = totalEstimated !== 0
  ? Math.round((totalCostVariance / totalEstimated) * 1000) / 10
  : null;

const totalQtyVarianceItems = variances.filter(v => v.qtyVarianceAmount !== 0).length;

return [{
  json: {
    variances,
    totalActual: Math.round(totalActual * 100) / 100,
    totalEstimated: Math.round(totalEstimated * 100) / 100,
    totalCostVariance,
    totalCostVariancePct,
    totalQtyVarianceItems
  }
}];

