const msg = $input.item.json;

const senderName = msg.from.value[0].name;
const senderEmail = msg.from.value[0].address;
const sanitizedSender = senderName.replace(/[\/\\:*?"<>|]/g, '');
const dateReceived = msg.date.split('T')[0];

return {
  json: {
    label: "invoice",
    messageId: msg.id,
    senderName,
    senderEmail,
    sanitizedSender,
    subject: msg.subject,
    dateReceived,
    attachmentCount: Object.keys($input.item.binary || {}).length,
  },
  binary: $input.item.binary,
};

